    if data.diagnostics.iter().any(|d| d.code == DiagnosticCode::ParseError) {
        return "parse error".to_owned();
    }
    let mut found: Vec<String> =
        data.component_mappings.iter().map(|m| format!("{}:{}", m.component_name, m.props_type_name)).collect();
    found.sort();
