import json, subprocess, sys

base_bin, head_bin = sys.argv[1], sys.argv[2]
corpora = "/Users/gabe/.cache/caliper/corpora/repos"
dirs = [
    "mantine/packages/@mantine/core/src",
    "chakra-ui/packages/react/src",
    "shadcn-ui/apps/v4",
    "ant-design/components",
    "react-spectrum/packages",
]


def degraded(value):
    found = []
    if isinstance(value, dict):
        code = str(value.get("code", ""))
        if code.replace("-", "_").upper() == "SEMANTIC_BACKEND" and str(value.get("severity", "")).lower() != "info":
            found.append(value)
        for child in value.values():
            found += degraded(child)
    elif isinstance(value, list):
        for child in value:
            found += degraded(child)
    return found


def run(binary, src):
    r = subprocess.run(
        [binary, "extract", "--src", src, "--quiet", "--no-cache", "--load-dependencies", "--json"],
        capture_output=True, text=True,
    )
    if r.returncode != 0:
        return r.returncode, None
    out = json.loads(r.stdout)
    out.pop("stats", None)
    return 0, out


def count(out):
    for key in ("components", "component_entries"):
        if isinstance(out.get(key), (list, dict)):
            return len(out[key])
    return "?"


for d in dirs:
    src = f"{corpora}/{d}"
    base_code, base = run(base_bin, src)
    head_code, head = run(head_bin, src)
    if base is None or head is None:
        print(f"{d}: exit base {base_code} head {head_code}")
        continue
    bad = degraded(base) + degraded(head)
    verdict = "identical" if base == head else "DIFFERENT"
    print(f"{d}: {verdict}, components {count(base)}/{count(head)}, non-info SEMANTIC_BACKEND {len(bad)}", flush=True)
    if base != head:
        json.dump(base, open(f"/tmp/claude-501/oxc4/{d.split('/')[0]}.base.json", "w"), indent=1, sort_keys=True)
        json.dump(head, open(f"/tmp/claude-501/oxc4/{d.split('/')[0]}.head.json", "w"), indent=1, sort_keys=True)

